async function api(path, {method='GET',body,scoped=true}={}) {
  const u=new URL(path,location.origin); if(scoped&&S.clientId)u.searchParams.set('clientId',S.clientId);
  const headers={Accept:'application/json'};if(body!==undefined)headers['Content-Type']='application/json';if(S.session?.csrf)headers['X-CSRF-Token']=S.session.csrf;
  const response=await fetch(u,{method,headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)});
  const contentType=response.headers.get('content-type')||'';
  const result=contentType.includes('application/json')?await response.json():await response.text();
  if(!response.ok)throw new Error(result.error||result.message||'Operazione non riuscita. Riprova.');return result;
}
