function fieldsHTML(fields){return `<div class="form-grid">${fields.map(f=>{if(Object.hasOwn(f,'html'))return f.html?`<div class="field full">${f.html}</div>`:'';const id='field-'+f.name,v=f.value??'',required=f.required?'required':'';if(f.type==='checkbox')return `<div class="field full"><label class="check-field"><input type="checkbox" name="${e(f.name)}" ${v?'checked':''}><span>${e(f.label)}</span></label>${f.help?`<small>${e(f.help)}</small>`:''}</div>`;let input=f.type==='textarea'?`<textarea id="${id}" name="${e(f.name)}" ${required}>${e(v)}</textarea>`:f.type==='select'?`<select id="${id}" name="${e(f.name)}" ${required}>${(f.options||[]).map(o=>`<option value="${e(Array.isArray(o)?o[0]:o)}" ${String(Array.isArray(o)?o[0]:o)===String(v)?'selected':''}>${e(Array.isArray(o)?o[1]:label(o))}</option>`).join('')}</select>`:`<input id="${id}" name="${e(f.name)}" type="${f.type||'text'}" value="${e(v)}" ${required} ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''} ${f.step?`step="${f.step}"`:''} ${f.placeholder?`placeholder="${e(f.placeholder)}"`:''}>`;return `<div class="field ${f.full?'full':''}"><label for="${id}">${e(f.label)}</label>${input}${f.help?`<small>${e(f.help)}</small>`:''}</div>`;}).join('')}</div>`;}
