function scheduleTriggerName(trigger,state=S.module){
  const calendar={daily:'Ogni giorno alle 9','weekly-monday':'Lunedì alle 9','weekly-friday':'Venerdì alle 9',monthly:'Primo del mese alle 9'};
  if(calendar[trigger])return calendar[trigger];
  const key=String(trigger).replace(/^event:/,'');return (state.eventDefinitions||[]).find(x=>x.id===key||x.id===trigger)?.name||'Su evento';
}
function agentValue(value){
  if(value===null||value===undefined)return '';
  if(Array.isArray(value))return value.map(agentValue).filter(Boolean).join('\n');
  if(typeof value==='object')return value.text||value.content||value.body||value.description||value.name||value.label||value.reason||value.title||Object.values(value).map(agentValue).filter(Boolean).join(' · ');
  return String(value);
}
function agentSources(sources){return asArray(sources).length?`<ul class="plain-list">${asArray(sources).map(source=>`<li>${e(agentValue(source))}</li>`).join('')}</ul>`:'<p class="muted">Nessuna fonte registrata: il risultato richiede verifica.</p>';}
function agentRelatedLinks(links,fallbackService){
  return asArray(links).map(link=>{
    if(typeof link==='string')return '';
    if(!link||typeof link!=='object')return '';
    let view=link.view||link.module||(link.leadId||link.leadIds||link.messageId?'growth':link.campaignId||link.programId?'fidelity':link.contentId?'work':'')||({growth:'growth',fidelity:'fidelity',social:'work'})[fallbackService];
    if(view==='work'||view==='production'||link.contentId)return btn(link.label||link.title||'Apri bozza collegata','agent-content',link.contentId||'','small','arrow');
    if(!view&&typeof link.href==='string'&&link.href.startsWith('#'))view=link.href.slice(1);
    if(view&&(/^(?:work|growth|fidelity|administration|marketing|approvals|activity|agency)$/.test(view)||/^service:[a-z-]+$/.test(view)))return btn(link.label||link.title||'Apri lavoro collegato','agent-related',view,'small','arrow');
    return '';
  }).join('');
}
async function openAgentOutput(outputId,clientId,fallback={}){
  const snapshot=viewSnapshot();
  const response=await api('/api/agents/outputs/'+encodeURIComponent(outputId)+'?clientId='+encodeURIComponent(clientId),{scoped:false});
  if(!isCurrentView(snapshot))return;
  const output=response.output||response;S.agentOutput={...fallback,...output,id:output.id||outputId,client_id:output.client_id||clientId};
  showAgentOutput(S.agentOutput);
}
function showAgentOutput(output){
  const missing=output.missingInputs||[],sources=output.sources||[],body=output.body||'',sections=asArray(output.sections),pending=approvalItems().find(a=>a.status==='pending'&&((a.kind==='agent_output'&&a.entity_id===output.id)||a.id===output.approvalId||a.id===output.links?.approvalId));
  const history=asArray(output.versions||output.history);
  dialog(output.title||'Elaborato dello sciame',`<div class="pill-row">${badge('Procedura DEMO offline')}${output.status?badge(output.status):''}${output.version?badge('Versione '+output.version):''}</div><p class="preserve section">${e(output.summary||'Elaborato interno del workspace.')}</p>${output.prerequisite||missing.length?notice('La procedura segnala dati da completare. Questo elaborato non certifica l’esecuzione di un servizio esterno.',true):''}${body?`<section class="agent-output-body preserve section">${e(body)}</section>`:''}${!body&&sections.length?sections.map(section=>`<section class="section"><h3>${e(section.title||section.name||'Dettaglio')}</h3><div class="preserve">${e(agentValue(section.items||section.content||section.body||section.text))}</div></section>`).join(''):''}${missing.length?`<h3 class="section">Cosa manca per proseguire</h3>${agentSources(missing)}`:''}<h3 class="section">Fonti usate</h3>${agentSources(sources)}<p class="muted">Costo della procedura DEMO: ${money(output.costCents??0)}. Nessun invio o pubblicazione.</p>${history.length?`<details class="structure-detail section"><summary><span><strong>Versioni conservate · ${history.length}</strong></span><span class="expand-mark">+</span></summary><div class="structure-body">${history.map(version=>`<p><strong>Versione ${e(version.version)}</strong> · ${e(label(version.status||''))}<br>${e(version.title||'Elaborato')}<small>${version.created_at?' · '+date(version.created_at,true):''}</small></p>`).join('')}</div></details>`:''}<div class="actions section">${output.id&&isOwner()&&!output.revisionInModule&&!output.prerequisite?btn('Modifica elaborato','edit-agent-output',output.id,'small'):''}${pending?btn('Rivedi e decidi','approval',pending.id,'primary small','approval'):!output.prerequisite&&!output.revisionInModule?btn('Apri le approvazioni','goto','approvals','small','approval'):''}${agentRelatedLinks(output.links||[{}],output.service)}</div><p class="footnote">${output.prerequisite?'Completa i dati richiesti e prepara un nuovo giro. Questo esito non richiede approvazione.':output.revisionInModule?'Modifica la bozza nel modulo collegato. La sua approvazione rimane nella coda comune.':'Una modifica conserva la versione precedente e richiede una nuova approvazione.'}</p>`);
}
async function runAgentQueue(all=false){
  if(S.agentBusy)return;
  const clientId=S.clientId;S.agentBusy=true;S.agentProgress={clientId,running:true,title:all?'Preparo il giro dell’attività…':'Eseguo la coda DEMO…',detail:'Ogni lavoro mantiene fonte, stato e costo nel registro.'};render();
  const request=(path,body={})=>api(path+'?clientId='+encodeURIComponent(clientId),{method:'POST',body,scoped:false});
  try{
    let before=await api('/api/agents/state?clientId='+encodeURIComponent(clientId),{scoped:false});
    let ids=new Set((before.jobs||[]).filter(j=>j.client_id===clientId&&['queued','running'].includes(j.status)).map(j=>j.id));
    if(all){
      const previous=new Set((before.jobs||[]).map(j=>j.id));
      await request('/api/agents/run-all');
      const queued=await api('/api/agents/state?clientId='+encodeURIComponent(clientId),{scoped:false});
      ids=new Set((queued.jobs||[]).filter(j=>j.client_id===clientId&&!previous.has(j.id)).map(j=>j.id));
      S.agentProgress={clientId,running:true,title:'Procedure accodate. Avvio la prova…',detail:`${ids.size} nuovi lavori registrati. Le approvazioni rimarranno da decidere.`};if(S.view==='agents')render();
    }
    const result=await request('/api/agents/drain',{limit:40});
    const after=await api('/api/agents/state?clientId='+encodeURIComponent(clientId),{scoped:false}),selected=(after.jobs||[]).filter(j=>ids.has(j.id)),done=selected.filter(j=>j.status==='done').length,needsInput=selected.filter(agentNeedsInput).length,failed=selected.filter(j=>j.status==='failed').length,pending=selected.filter(j=>['queued','running'].includes(j.status)).length;
    S.agentProgress={clientId,running:false,error:failed>0,title:after.paused?'Coda conservata: sciame in pausa':failed?'Giro concluso con attività da verificare':pending?'Giro completato, restano lavori in coda':selected.length?'Giro DEMO completato':'Nessun lavoro in coda',detail:`${done} elaborati prodotti (${needsInput} con dati da completare) · ${pending} in attesa · ${failed} errori. ${after.paused?'Riattiva gli agenti per proseguire.':'Apri gli elaborati e decidi le approvazioni.'}`,completed:done,total:selected.length};
    if(result.error)S.agentProgress.detail+=' '+result.error;
    toast(S.agentProgress.title,failed>0);
  }catch(error){S.agentProgress={clientId,running:false,error:true,title:'Il giro richiede una verifica',detail:error.message+' Le attività già accodate restano salvate: aggiorna i dati e completa la coda senza ripetere la prova.'};throw error;}
  finally{S.agentBusy=false;await load();}
}


