function parseCSV(value){const rows=[];let row=[],cell='',quoted=false;const csv=value.replace(/^\uFEFF/,'');for(let i=0;i<csv.length;i++){const ch=csv[i];if(ch==='"'){if(quoted&&csv[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if(ch==='\n'&&!quoted){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw Error('CSV non valido: virgolette non chiuse.');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row);}const headers=(rows.shift()||[]).map(x=>x.trim());if(!headers.includes('company'))throw Error('Serve la colonna company con il nome dell’azienda.');return rows.filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])));}

