  'run-agent':async id=>{
    if(S.agentBusy)throw Error('Attendi il completamento del giro già avviato.');
    const clientId=S.clientId,agent=S.module.definitions.find(x=>x.id===id);if(!agent||agent.status!=='implemented'||agent.eligible===false)throw Error(agent?.unavailableReason||'Procedura non disponibile per questa attività.');
    const fields=[];
    if(['research','analyst','commercial'].includes(id))fields.push({name:'query',label:'Settore e zona della ricerca DEMO',value:id==='research'?'Attività locali a Caserta DEMO':'',full:true,required:id==='research',help:'Usa soltanto dati di esempio. La ricerca non consulta il web.'});
    if(['analyst','commercial'].includes(id)){
      const growth=await api('/api/growth/state?clientId='+encodeURIComponent(clientId),{scoped:false});
      fields.push({name:'leadId',label:'Azienda DEMO da usare',type:'select',options:[['','Contesto dimostrativo della procedura'],...(growth.leads||[]).map(lead=>[lead.id,lead.company])],full:true,help:'Puoi scegliere un contatto della stessa attività. I dati mancanti saranno segnalati.'});
    }
    fields.push({name:'brief',label:'Indicazioni per questo giro',type:'textarea',full:true,help:'Facoltativo. Aggiungi un obiettivo o un vincolo inventato; la procedura userà anche la memoria dell’attività.'});
    form(agent.name,fields,async(b,fd,key)=>{
      const input=Object.fromEntries(Object.entries(b).filter(([,value])=>String(value).trim()));
      await api('/api/agents/run?clientId='+encodeURIComponent(clientId),{method:'POST',body:{agent:id,input,dedupe:'ui:'+key},scoped:false});
      S.agentProgress={clientId,running:false,title:'Procedura aggiunta alla coda',detail:'Premi “Esegui prossima” o “Completa la coda” per leggere l’elaborato. Nessuna approvazione viene concessa automaticamente.'};
      await saved('Procedura DEMO accodata');
    },{submit:'Accoda procedura DEMO',intro:clientName(clientId)+' · '+agent.purpose+' · Costo DEMO zero, nessun servizio esterno.'});
  },
  'agents-run-all':()=>runAgentQueue(true),
  'agents-drain':()=>runAgentQueue(false),
