Object.assign(ACTIONS,{
  'fidelity-policies':()=>{const c=S.overview.currentClient;form(S.module.demo?'Regolamento e privacy DEMO':'Regolamento e privacy',[{name:'privacyUrl',label:'Link informativa privacy',type:'url',value:c.privacy_url,full:true,placeholder:'https://privacy.example'},areaField('termsText',S.module.demo?'Regolamento della prova':'Regolamento',c.terms_text||(S.module.demo?'Programma dimostrativo con dati inventati. Nessuna tessera Wallet reale o promessa commerciale.':''))],async b=>{await mutate('/api/fidelity/settings/policies',b,'PATCH');await saved('Informazioni del programma aggiornate');},{intro:S.module.demo?'Testi dimostrativi da sostituire con documenti verificati prima di qualsiasi utilizzo reale.':'Inserisci i documenti verificati dell’attività. Saranno visibili nella pagina di iscrizione.'});},
  'program-logo':id=>form('Logo del programma',[{name:'logo',label:'Immagine PNG, JPEG o WebP',type:'file',required:true,full:true,help:'Massimo 512 KiB e 2 milioni di pixel. Il server ricrea un PNG sicuro.'}],async(b,fd)=>{const file=fd.get('logo');if(!file?.size)throw Error('Seleziona un’immagine.');if(file.size>512*1024)throw Error('Scegli un’immagine non superiore a 512 KiB.');const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Immagine non leggibile.'));r.readAsDataURL(file);});await mutate('/api/fidelity/programs/'+id+'/logo',{dataUrl});await saved('Logo del programma aggiornato');})
});
Object.assign(ACTIONS,{
  'credentials-login':()=>form(S.session?.demo===false?'Accedi a BigAnt OS':'Accesso utente DEMO',[{name:'email',label:S.session?.demo===false?'Email':'Email .example',type:'email',required:true,full:true},{name:'password',label:S.session?.demo===false?'Password':'Password del prototipo',type:'password',required:true,full:true}],async b=>{S.session=await mutate('/api/login',b);$('#dialog').close();S.clientId='';S.view=role()==='client'?'client':'home';await load();},{submit:'Accedi',intro:S.session?.demo===false?'Usa il tuo account BigAnt OS.':'Usa un utente creato nella sezione Accessi del prototipo. Non inserire le credenziali dei tuoi account reali.'}),
  'new-user':()=>form(S.session?.demo===false?'Nuovo accesso':'Nuovo utente DEMO',[textField('name',S.session?.demo===false?'Nome e cognome':'Nome di esempio','',true),{name:'email',label:S.session?.demo===false?'Email':'Email .example',type:'email',required:true,full:true},selectField('role','Ruolo',[['collaborator','Collaboratore'],['client','Cliente'],['owner','Socio BigAnt']]),selectField('clientId','Attività del cliente',options(S.overview.clients)),{name:'password',label:S.session?.demo===false?'Password provvisoria':'Password dedicata al prototipo',type:'password',required:true,full:true,help:S.session?.demo===false?'Almeno 14 caratteri. La persona la cambierà al primo accesso.':'Almeno 14 caratteri. Non riutilizzare password di account reali.'},{html:`<label>Attività assegnate al collaboratore</label><div class="service-checks">${S.overview.clients.map(c=>`<label><input type="checkbox" name="clientIds" value="${e(c.id)}">${e(c.name)}</label>`).join('')}</div>`}],async(b,fd)=>{if(S.session?.demo!==false)demoEmail(b.email);await mutate('/api/users',{...b,name:S.session?.demo===false?b.name:(b.name.includes('DEMO')?b.name:b.name+' · DEMO'),clientIds:fd.getAll('clientIds')});await saved(S.session?.demo===false?'Accesso creato':'Utente DEMO creato');},{intro:'Per il cliente scegli una sola attività. Per il collaboratore seleziona le attività assegnate. I soci hanno accesso completo.'}),
  'reset-user':id=>{const u=S.module.items.find(x=>x.id===id);form('Nuova password · '+u.name,[{name:'password',label:S.session?.demo===false?'Nuova password provvisoria':'Nuova password del prototipo',type:'password',required:true,full:true,help:'Almeno 14 caratteri; viene salvata solo come impronta protetta.'}],async b=>{await mutate('/api/users/'+id,b,'PATCH');if(id===S.session.user.id){$('#dialog').close();S.session=await api('/api/session',{scoped:false});login();toast('Password aggiornata. Accedi di nuovo.');}else await saved('Password aggiornata e sessioni precedenti chiuse');},{intro:S.session?.demo===false?'Le sessioni aperte verranno chiuse. Al prossimo accesso la persona dovrà scegliere una password personale.':'La modifica chiude le sessioni di questo utente nel prototipo.'});},
  'toggle-user':async id=>{const u=S.module.items.find(x=>x.id===id);await mutate('/api/users/'+id,{active:!u.active},'PATCH');toast(u.active?'Accesso disattivato':'Accesso riattivato');await load();}
});
ACTIONS['forgot-password']=()=>dialog('Recupera il tuo accesso',`<p>Contatta un socio BigAnt per ricevere una nuova password provvisoria. Al prossimo accesso potrai sceglierne una personale.</p><p>Se sei un socio, rivolgiti all’altro socio o al responsabile del server.</p>${btn('Ho capito','close','','primary')}`);
let fidelityCamera=null;
function stopCamera(){fidelityCamera?.stop();fidelityCamera=null;}
ACTIONS.camera=async()=>{
 stopCamera();const video=$('#camera-video'),status=$('#camera-status');
 status.textContent='Inquadra il codice della tessera.';
 fidelityCamera=new window.BigAntScanner({video,onCode:code=>{const form=$('#modal-form');if(!form||!$('#dialog').open)return;form.elements.code.value=code;status.textContent='Codice letto. Premi Cerca per aprire la tessera.';},onError:message=>{status.textContent=message;}});
 await fidelityCamera.start();
};
$('#dialog').addEventListener('close',stopCamera);

document.addEventListener('click',async event=>{const view=event.target.closest('[data-view]');if(view){event.preventDefault();await go(view.dataset.view);return;}const button=event.target.closest('[data-action]');if(!button)return;event.preventDefault();const action=ACTIONS[button.dataset.action];if(!action)return;button.disabled=true;try{await action(button.dataset.id);}catch(error){toast(error.message,true);}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('submit',async event=>{const f=event.target;if(!['account-login','account-password','modal-form','ask-form','research-form','public-join','public-book','public-inquiry'].includes(f.id))return;event.preventDefault();const submit=f.querySelector('button[type=submit]'),errorBox=f.querySelector('.form-error');if(submit)submit.disabled=true;if(errorBox)errorBox.hidden=true;try{const fd=new FormData(f),b=Object.fromEntries(fd);if(f.id==='account-login'){S.session=await api('/api/login',{method:'POST',body:b,scoped:false});S.clientId='';S.overview=null;setViewRoute(role()==='client'?'client':'home');history.replaceState(null,'','#'+S.view);await load();}
else if(f.id==='account-password'){S.session=await api('/api/account/password',{method:'POST',body:b,scoped:false});S.overview=null;await load();toast('Password personale salvata.');}
else if(f.id==='modal-form')await formHandler(fd);
else if(f.id==='ask-form'){const result=await mutate('/api/production/ask',{question:b.question,createTask:fd.has('createTask')});$('#ask-answer').textContent=result.answer+(result.taskId?'\n\nLa richiesta è stata aggiunta ai lavori del team.':'');}
else if(f.id==='research-form'){if(S.module.settings.paused){if(!S.module.simulation)throw new Error('Riprendi le attività prima della ricerca.');await mutate('/api/growth/settings',{paused:false});}await mutate('/api/growth/jobs',{type:'research',query:b.query});const result=await mutate('/api/growth/jobs/run');toast(result.job?.status==='failed'?result.job.error:(S.module.simulation?'Ricerca DEMO eseguita. Le analisi sono in coda.':'Attività eseguita. Consulta aziende e coda per gli esiti.'));await load();}
else if(f.id==='public-join'){if(publicContext.data.demo)demoEmail(b.email);const r=await api('/api/fidelity/public/join/'+encodeURIComponent(publicContext.slug),{method:'POST',body:{...b,name:!publicContext.data.demo||b.name.includes('DEMO')?b.name:b.name+' · DEMO',acceptTerms:fd.has('acceptTerms'),marketingConsent:fd.has('marketingConsent')},scoped:false});location.href=r.cardUrl;}
else if(f.id==='public-book')await submitPublicBooking(b,fd);
else if(f.id==='public-inquiry'){demoEmail(b.email);await api('/api/growth/public/inquiry',{method:'POST',body:{...b,privacyAcknowledged:fd.has('privacyAcknowledged'),marketing:fd.has('marketing')},scoped:false});publicShell('Richiesta DEMO registrata','<p>È disponibile nel CRM di BigAnt. Nessuna email viene inviata.</p>');}
}catch(error){if(errorBox){errorBox.textContent=error.message;errorBox.hidden=false;}else toast(error.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('change',async event=>{try{if(event.target.id==='approval-type'){S.approvalFilter=event.target.value;render();return;}if(event.target.id==='calendar-month'){if(/^\d{4}-\d{2}$/.test(event.target.value)){S.calendarMonth=event.target.value;render();}return;}if(event.target.id==='client-picker'){S.clientId=event.target.value;S.filter='';await load();}if(event.target.id==='public-consent'){const desired=event.target.checked;try{await api('/api/fidelity/public/cards/'+publicContext.token+'/consent',{method:'PATCH',body:{marketingConsent:desired},scoped:false});toast('Preferenza aggiornata');}catch(error){event.target.checked=!desired;throw error;}}if(event.target.name==='entityId'&&$('#modal-form [name=accountId]')){const account=$('#modal-form [name=accountId]');account.innerHTML=adminData().accounts.filter(x=>x.entity_id===event.target.value).map(x=>`<option value="${e(x.id)}">${e(x.name)}</option>`).join('');}if(event.target.name==='invoiceId'&&event.target.value){const a=adminData(),i=a.invoices.find(x=>x.id===event.target.value),f=$('#modal-form');f.elements.entityId.value=i.entity_id;f.elements.entityId.dispatchEvent(new Event('change',{bubbles:true}));f.elements.counterpartyId.value=i.counterparty_id;f.elements.amountEuros.value=(i.remaining_cents/100).toFixed(2);f.elements.kind.value='income';if(f.elements.obligationId)f.elements.obligationId.value='';if(f.elements.subscriptionId)f.elements.subscriptionId.value='';}if(['obligationId','subscriptionId'].includes(event.target.name)&&event.target.value){const a=adminData(),isObligation=event.target.name==='obligationId',x=(isObligation?a.obligations:a.subscriptions).find(x=>x.id===event.target.value),f=$('#modal-form');f.elements.entityId.value=x.entity_id;f.elements.entityId.dispatchEvent(new Event('change',{bubbles:true}));f.elements.counterpartyId.value=x.counterparty_id||'';f.elements.amountEuros.value=((isObligation?x.remaining_cents:x.amount_cents)/100).toFixed(2);f.elements.kind.value=x.kind==='owner_agreement'?'withdrawal':'expense';f.elements.invoiceId.value='';f.elements[isObligation?'subscriptionId':'obligationId'].value='';}}catch(error){toast(error.message,true);}});
let filterTimer;document.addEventListener('input',event=>{if(event.target.id!=='local-filter')return;const value=event.target.value,position=event.target.selectionStart;clearTimeout(filterTimer);filterTimer=setTimeout(()=>{S.filter=value;render();const field=$('#local-filter');field?.focus();field?.setSelectionRange(position,position);},180);});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('#dialog').close();}});
setInterval(async()=>{if(!S.session?.user||!['agents','growth'].includes(S.view)||$('#dialog').open||document.hidden||document.activeElement?.matches('input,textarea,select,[contenteditable=true]')||S.refreshing||S.agentBusy||Date.now()-(S.lastRefresh||0)<7500)return;S.refreshing=true;try{await load();}finally{S.refreshing=false;}},8000);
async function start(){try{if(await publicPage())return;S.session=await api('/api/session',{scoped:false});if(!S.session.user)return login();setViewRoute(location.hash.slice(1)||(role()==='client'?'client':'home'));await load();}catch(error){publicShell('Non riesco ad aprire questa pagina',`${notice(error.message)}<a class="btn" href="/">Torna al workspace</a>`,!location.pathname.startsWith('/growth/book/'));}}
start();

// Clear revealed credentials and form values as soon as their dialog closes.
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open){$('#dialog-content').replaceChildren();formHandler=null;}});
